#!/usr/bin/env python3
"""Generate the English ver4 subpages from one narrative and visual system.

The homepage stays hand-crafted. This generator owns every English HTML page
except index.html and keeps the prototype coherent while the information
architecture is still evolving.
"""
from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
VERSION = "20260813"


