    if kind == "process":
        return '''<div class="v4p-canvas v4p-diagram-process"><span class="v4p-canvas-label">STATE-BASED PROCESS ENGINE</span><svg viewBox="0 0 560 500" aria-hidden="true"><defs><marker id="v4pArrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 10 5 0 10z" fill="#64748b"/></marker></defs><path d="M154 136h70M336 136h70M464 168v130M406 329h-68M220 329h-68M96 298V168" fill="none" stroke="#475569" stroke-width="2" stroke-dasharray="6 6" marker-end="url(#v4pArrow)"/></svg><div class="v4p-state s1">Draft</div><div class="v4p-state s2">AI check</div><div class="v4p-state s3">Review</div><div class="v4p-state s4">Approval</div><div class="v4p-state s5">Active</div><p class="v4p-visual-caption">State defines what can happen next, who may act and which rules apply.</p></div>'''
